\label{def:uniongraph}
The {\em union (simple) graph} $G'=(V,E')$ of $G_1,\ldots,G_Q$ is defined as the graph on $V$,  whose edges are given by the set  $E'=\cup_{i=1}^Q E_i$. 
\hfill $\blacksquare$

\label{def:multigraph}
The {\em union multigraph} $G=(V,E)$ of $G_1,\ldots,G_Q$ is defined as the multigraph on $V$, whose edges are given by the multiset $E=\biguplus_{i=1}^Q E_i$. 
\hfill $\blacksquare$

\caption{Multigraph Sampling Algorithm}
\begin{algorithmic}[1]
\REQUIRE {$v_0\in V$, simple graphs $G_i, i=1\ldots Q$}
\STATE {Initialize $v \leftarrow v_0$.}
\WHILE{\textsc{not Converged}}

\STATE {Select graph $G_i$ with probability $\frac{d_i(v)}{d(v)}$}
\STATE {Select uniformly at random a neighbor $v'$ of $v$ in $G_i$}
\STATE {$v \leftarrow v'$}
\ENDWHILE
\RETURN{all sampled nodes $v$ and their degrees $d(v)$.}
\end{algorithmic}
\label{alg:mixture}

